export type IssueStatus =
  | "backlog"
  | "todo"
  | "in_progress"
  | "in_review"
  | "done"
  | "canceled";

export type IssueStatusFilter = IssueStatus | "open" | "closed";

export const ISSUE_STATUSES: readonly IssueStatus[] = [
  "backlog",
  "todo",
  "in_progress",
  "in_review",
  "done",
  "canceled",
];

/** Statuses that count as closed for stats, digests and overdue checks. */
export const CLOSED_ISSUE_STATUSES: readonly IssueStatus[] = ["done", "canceled"];

export function expandIssueStatusFilters(
  values: readonly IssueStatusFilter[],
): readonly IssueStatus[] {
  const expanded = new Set<IssueStatus>();
  for (const value of values) {
    if (value === "open") {
      ISSUE_STATUSES.filter((status) => !CLOSED_ISSUE_STATUSES.includes(status))
        .forEach((status) => expanded.add(status));
    } else if (value === "closed") {
      CLOSED_ISSUE_STATUSES.forEach((status) => expanded.add(status));
    } else {
      expanded.add(value);
    }
  }
  return [...expanded];
}

export type IssuePriority = "none" | "low" | "medium" | "high" | "urgent";

export const ISSUE_PRIORITIES: readonly IssuePriority[] = [
